import {toolBanner} from './tool-banner.mjs';
import {defaultRules,checkFormatting,validateRules} from './format-model.mjs';
import {parseDocx,applyDocx,exampleDocx} from './assets/format-document.js';
import {keys,list,projects,write,recordTask} from './state.mjs';
import {esc,icon,download} from './ui.mjs';
let root,ctx,item,doc,bytes,rules,checked=false,applied=null,dirty=false,busy=false,controller,view='original',tab='base',focus=0,formatStep=1,formatService='smart',templateChoice='custom';
let formatEpoch=0;
export function disposeFormat(){formatEpoch++;controller?.abort();controller=null;root=null;dirty=false;busy=false;}
const $=s=>root?.querySelector(s),to64=b=>{let s='';for(let i=0;i<b.length;i+=8192)s+=String.fromCharCode(...b.slice(i,i+8192));return btoa(s);},from64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
export const formatHasWork=()=>!!root?.querySelector('.format-space')&&(dirty||busy);
export function formatRouteGuard(){if(!root?.querySelector('.format-space'))return true;if(busy){ctx.notify('文档处理中，请稍候。');return false;}if(dirty&&!confirm('有未保存的排版设置，确定离开？原始文件不会被修改。'))return false;dirty=false;return true;}
window.addEventListener('beforeunload',e=>{if(formatHasWork()){e.preventDefault();e.returnValue='';}});
export async function mountFormat(context,id,projectId){disposeFormat();const epoch=formatEpoch;controller=new AbortController();ctx=context;root=document.querySelector('.dashboard');const loaded=list(keys.drafts).find(d=>String(d.id)===String(id)&&d.tool==='format')||{title:'毕业论文示例',projectId:projectId||'',example:true};item=loaded;const routeParams=new URLSearchParams(String(window.location.hash).split('?')[1]||'');formatService=['check','smart','refine'].includes(routeParams.get('service'))?routeParams.get('service'):['check','smart','refine'].includes(loaded.formatting?.service)?loaded.formatting.service:'smart';templateChoice=['custom','undergraduate','graduate'].includes(loaded.formatting?.template)?loaded.formatting.template:'custom';rules={...defaultRules(),...loaded.formatting?.rules};checked=loaded.formatting?.checked===true;applied=null;dirty=false;busy=true;view='original';tab='base';focus=0;formatStep=formatService==='refine'?1:loaded.formatting?.applied||formatService==='check'&&checked?4:1;root.innerHTML=`<div class="format-space">${toolBanner('format',{extraClass:'detail-service-banner',description:'正在读取本地文档…'})}</div>`;try{const incoming=loaded.formatting?.original?from64(loaded.formatting.original):await exampleDocx();if(epoch!==formatEpoch)return;const parsed=await parseDocx(incoming);if(epoch!==formatEpoch)return;if(loaded.formatting?.levels)parsed.paragraphs.forEach((p,i)=>{const l=loaded.formatting.levels[i];if([0,1,2,3].includes(l))p.level=l;});let formatted=null;if(loaded.formatting?.applied){formatted=await applyDocx(incoming,parsed,rules);if(epoch!==formatEpoch)return;}bytes=incoming;doc=parsed;applied=formatted;if(id&&!loaded.formatting){ctx.notify('旧记录未包含原文文件，请重新上传 DOCX。原记录未被修改。');item={...loaded,title:loaded.title||'毕业论文示例',example:true};}if(formatted){checked=true;view='formatted';}draw();root.addEventListener('click',actions,{signal:controller.signal});root.addEventListener('change',changes,{signal:controller.signal});root.addEventListener('input',changes,{signal:controller.signal});}catch(e){if(epoch===formatEpoch)root.innerHTML=`<div class="format-space">${toolBanner('format',{extraClass:'detail-service-banner',description:'文档读取失败，请重新上传或使用示例。',actions:'<a class="btn secondary" href="#category/format">重新开始</a>'})}<p class="hub-error" role="alert">${esc(e.message)}</p></div>`;}finally{if(epoch===formatEpoch)busy=false;}}
function select(key,label,values){return `<label>${label}<select data-rule="${key}" aria-label="${label}">${values.map(([v,t])=>`<option value="${v}" ${String(rules[key])===String(v)?'selected':''}>${t}</option>`).join('')}</select></label>`;}
const sizes=[[10.5,'五号 · 10.5pt'],[12,'小四 · 12pt'],[14,'四号 · 14pt'],[16,'三号 · 16pt'],[18,'小二 · 18pt']];
const formatStages=[['template','选择模板','先确定学校或通用排版规则'],['upload','上传论文','导入需要排版的 DOCX 文件'],['format','自动排版','检查并应用排版设置'],['download','下载结果','导出排版后的 Word 文档']];
const formatFlows={
 check:{title:'格式检测',desc:'选择通用或自定义规则，上传 DOCX，检查实际格式差异。',steps:[['template','选择模板','选择通用或自定义格式规则'],['upload','上传论文','上传需要检测的 DOCX 文档'],['detect','自动检测','生成格式问题清单'],['report','检测报告','查看问题位置与修改建议']]},
 smart:{title:'智能排版',desc:'按通用或自定义规则，检查并生成排版副本，原件保留。',steps:[['template','选择模板','选择通用或自定义格式规则'],['upload','上传论文','上传需要排版的 DOCX 文档'],['format','自动排版','检查并应用排版设置'],['download','下载结果','导出排版后的 Word 文档']]},
 refine:{title:'格式精修',desc:'人工格式精修尚未开放。当前可先了解流程，并保留本地原件。',steps:[['source','上传原文','上传需要精修的论文原文'],['template','上传格式模板','提供学校或期刊格式样例'],['process','等待处理','处理完成后查看精修结果'],['download','下载完成','下载格式精修后的文档']]}
};
const currentFlow=()=>formatFlows[formatService]||formatFlows.smart;
const isExampleDocument=()=>item.example===true||(!item.fileName&&/示例/.test(item.title||''));
const formatServices=[['check','格式检测','检查字体、字号、行距和页边距，生成问题清单。','search'],['smart','智能排版','按选定规则生成排版副本，并提供预览。','spark'],['refine','格式精修','人工精修服务尚未开放，可先了解交付流程。','pen']];
function formatServiceCards(){return `<section class="format-services" aria-label="格式排版服务"><div class="format-services-heading"><div><span class="format-flow-kicker">DOCUMENT FORMAT STUDIO</span><h2>规范的论文，从清晰的格式开始</h2><p>检测问题、整理版式或了解精修服务，每项都有独立的处理流程。</p></div><span class="hub-badge">本地处理 · 原件保留</span></div><div class="format-service-grid" role="group" aria-label="选择格式服务">${formatServices.map(([id,title,desc,ico])=>`<button type="button" class="format-service-card format-entry-${id} ${formatService===id?'active':''}" data-format-service="${id}" aria-pressed="${formatService===id}"><span class="format-service-icon">${formatServiceIcon(id,25)}</span><span class="format-service-copy"><span class="format-service-kicker">${id==='check'?'FORMAT CHECK':id==='smart'?'SMART LAYOUT':'REFINEMENT'}</span><strong>${title}</strong><small>${desc}</small><span class="format-service-delivery">${id==='check'?'交付：问题位置与格式清单':id==='smart'?'交付：排版副本与修改清单':'状态：人工精修尚未开放'}</span></span>${id==='refine'?'<b class="format-service-pending">待开放</b>':formatService===id?'<b class="format-service-check">已选择</b>':icon('arrow',15)}</button>`).join('')}</div></section>`;}
function formatServiceIcon(service,size=24){const paths={check:'M14 3H5v18h14V8zM14 3v5h5M8 12h5M8 16h3M19 16l3 3M21 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',smart:'M5 3h14v18H5zM8 7h8M8 11h8M8 15h8M8 18h4M2 7h1M2 11h1M2 15h1',refine:'M5 3h10l4 4v5M15 3v5h4M5 3v18h7M8 12h5M14 19l6-6 3 3-6 6h-3z'};return `<svg width="${size}" height="${size}" viewBox="0 0 26 26" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="${paths[service]||paths.smart}"/></svg>`;}


const formatTemplateCards=[['本科论文通用模板','适合本科毕业论文、课程论文'],['研究论文通用模板','适合硕士论文、研究报告'],['自定义当前规则','沿用你在下方设置的格式规则']];
function formatModePanel(){if(formatService==='refine')return `<section class="format-refine-panel"><div class="format-refine-intro"><span class="format-refine-illustration" aria-hidden="true">${formatServiceIcon('refine',52)}</span><div><span class="format-flow-kicker">FORMAT REFINEMENT · 待开放</span><h2>精修细节，让论文更接近提交标准</h2><p>人工精修尚未接入，当前可以本地读取原文并了解材料要求；不会创建人工服务订单或扣费。</p></div></div><div class="format-refine-upload-grid"><label class="format-refine-upload">${icon('upload',25)}<strong>论文原文</strong><small>DOCX · 最大 2MB · 仅在本地读取</small><span class="format-upload-action">选择原文 ${icon('arrow',14)}</span><input id="format-refine-file" type="file" aria-label="选择格式精修原文" accept=".docx"></label><div class="format-refine-upload pending">${icon('file',25)}<strong>学校或期刊格式模板</strong><small>服务开放后，用于核对具体格式要求</small><span class="format-refine-pending">暂未开放上传</span></div></div><p class="format-refine-file-note">${isExampleDocument()?'当前展示示例；尚未选择你的原文。':`本地原文：${esc(item.fileName||item.title+'.docx')} · ${doc.paragraphs.length} 个正文段落`}</p><div class="format-refine-foot"><span>${icon('shield',16)} 当前不提交人工处理，也不承诺交付时效。</span><button class="btn primary" type="button" disabled aria-disabled="true">人工精修 · 待开放</button></div></section>`;if(formatStep!==1)return '';return `<section class="format-mode-panel"><div class="format-template-heading"><div><h2>先选择适合的格式规则</h2><p>通用模板可作为起点，最终规范请以学校或期刊要求为准。</p></div><label class="format-template-search">${icon('search',16)}<input id="format-school-search" placeholder="搜索通用格式模板" aria-label="搜索格式模板"></label></div><div class="format-template-grid">${formatTemplateCards.map(([title,desc],i)=>{const value=['undergraduate','graduate','custom'][i],selected=templateChoice===value;return `<button type="button" class="format-template-card ${selected?'active':''}" data-template-choice="${i}" aria-pressed="${selected}"><span class="format-template-sheet" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></span><span class="format-template-copy"><strong>${title}</strong><small>${desc}</small><em>${selected?'当前规则':'使用此规则'} ${selected?'✓':'→'}</em></span></button>`;}).join('')}</div><p id="format-template-empty" class="format-template-empty" hidden>没有匹配的通用模板，可使用“自定义当前规则”。学校专用模板库尚未接入。</p></section>`;}

function formatFlowPanel(){
 const [key,title,desc]=currentFlow().steps[formatStep-1]||currentFlow().steps[0];
 const action=formatStep===1?'next-step':formatStep===2?'next-step':formatStep===3?(formatService==='check'?'check':formatService==='refine'?'refine-pending':'apply'):(formatService==='check'?'report':'export');
 const actionLabel=formatStep===1?(formatService==='refine'?'确认并上传原文':'确认模板，上传论文'):formatStep===2?(formatService==='refine'?'上传格式模板':formatService==='check'?'核对规则，开始检测':'核对规则，准备排版'):formatStep===3?(formatService==='check'?'检查格式':formatService==='refine'?'立即修改（待接入）':applied?'重新应用排版':'检查并应用排版'):(formatService==='check'?'查看检测报告':'下载排版结果');
 const helper=formatStep===1?(formatService==='refine'?'上传需要精修的论文原文，原文件不会被修改。':'选择通用论文模板，或使用自定义格式规则。学校专用模板库尚未开放。'):formatStep===2?(formatService==='refine'?'上传学校或期刊格式样例，当前仅保留本地文件。':'仅支持 DOCX，文件在当前浏览器本地读取，不会上传到云端。'):formatStep===3?(formatService==='check'?'当前为格式检测：生成问题清单，不会修改原文件。':formatService==='refine'?'当前为格式精修：在线精修服务尚未接入，可先保存本地需求。':'先检查格式差异，再应用可修正项。原始文件始终保留，复杂对象请在 Word 中核对。'):formatService==='check'?'检测报告会展示问题位置与规则建议。':'排版副本已生成。下载后请在 Word 中检查分页、目录、表格、图片和公式。';
 const templateControl=formatStep===1?(formatService==='refine'?`<div class="format-flow-template"><span>${isExampleDocument()?'尚未选择你的原文':'本地原文已读取'}</span><small>${isExampleDocument()?'当前仅为流程说明，不会提交人工处理。':'格式模板将在精修服务接入后使用，不会自动上传原文。'}</small></div>`:`<label class="format-flow-template">排版模板<select id="format-template-flow" aria-label="选择排版模板"><option value="custom">自定义当前规则</option><option value="undergraduate">本科论文通用模板</option><option value="graduate">研究论文通用模板</option></select></label>`):'';
 return `<section class="card format-flow-card" aria-label="格式排版流程"><span class="format-flow-symbol" aria-hidden="true">${formatServiceIcon(formatService,27)}</span><div class="format-flow-copy"><span class="format-flow-kicker">STEP ${String(formatStep).padStart(2,'0')} · ${key.toUpperCase()}</span><h2>${title}</h2><p>${desc}</p><span class="format-flow-document-state">${isExampleDocument()?'示例文档体验 · 尚未导入你的论文':`当前原文：${esc(item.fileName||item.title+'.docx')}`}</span></div><div class="format-flow-summary"><span class="hub-badge ${formatStep===4?'mint':''}">${formatService==='refine'?'服务待开放':formatStep===4?(formatService==='check'?'检测结果已就绪':'排版副本已就绪'):`步骤 ${formatStep}/4`}</span><p>${helper}</p></div>${templateControl}<div class="format-flow-actions">${formatStep>1?'<button class="btn secondary" data-action="prev-step">返回上一步</button>':''}<button class="btn primary" data-action="${action}" ${formatService==='refine'||formatStep===3&&doc.blocked?'disabled':''}>${actionLabel} ${icon(formatStep===4?'download':'arrow',15)}</button></div>${formatStep===2?'<label class="btn secondary format-upload format-flow-upload">'+icon('upload',16)+'选择 DOCX 文件<input id="format-file-flow" type="file" accept=".docx" aria-label="上传 DOCX 论文"></label>':''}</section>`;
}

function draw(){const issues=checked?checkFormatting(doc,rules):[],fix=issues.filter(i=>i.status==='fix').length,unknown=issues.length-fix;root.innerHTML=`<div class="format-space format-commercial doc-tool-detail doc-tool-format" data-format-mode="${formatService}">${toolBanner('format',{extraClass:'detail-service-banner',description:'上传 DOCX，按规范检查与整理文档格式。',actions:`<a class="btn secondary" href="#assets?scope=local">排版记录</a><label class="btn primary format-upload">${icon('upload',17)}上传论文<input id="format-file" type="file" accept=".docx" aria-label="上传 DOCX 论文"></label>`})}<div class="format-steps">${currentFlow().steps.map(([id,label,desc],i)=>`<button type="button" class="format-step ${formatService!=='refine'&&i+1===formatStep?'active':''} ${formatService!=='refine'&&i+1<formatStep?'done':''}" data-step="${i+1}" ${formatService==='refine'?'disabled aria-disabled="true"':''} aria-current="${formatService!=='refine'&&i+1===formatStep?'step':'false'}"><b>${formatService!=='refine'&&i+1<formatStep?'✓':i+1}</b><span><strong>${label}</strong><small>${desc}</small></span></button>`).join('')}</div>${formatFlowPanel()}<div class="format-grid ${formatStep<3||formatService==='refine'?'format-grid-hidden':''}"><section class="card format-settings doc-detail-panel"><div class="hub-card-heading"><h2>排版规范</h2><span class="hub-badge">${isExampleDocument()?'示例文档 · 请上传你的论文':'用户文档'}</span></div><div class="format-file">${icon('file',25)}<div><b>${esc(item.fileName||item.title+'.docx')}</b><small>${doc.paragraphs.length} 个正文段落 · ${doc.chars} 字符</small></div><button class="text-btn" data-action="original">下载原件</button></div><label class="research-field">成果名称<input id="format-title" aria-label="成果名称" maxlength="120" value="${esc(item.title)}"></label><label class="research-field">所属项目<select id="format-project" aria-label="所属项目"><option value="">未归入项目</option>${projects().map(p=>`<option value="${esc(p.id)}" ${item.projectId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="research-field">选择模板<select id="format-template" aria-label="选择模板"><option value="custom">自定义当前规则</option><option value="undergraduate">本科论文通用模板</option><option value="graduate">研究论文通用模板</option></select></label><p class="hub-footnote">通用规则并非学校或期刊官方模板，请核对实际要求。纸张与页眉页码保留原文件设置。</p><div class="research-tabs">${[['base','基础设置'],['heading','标题设置'],['scope','应用范围']].map(([v,t])=>`<button data-tab="${v}" class="${tab===v?'active':''}">${t}</button>`).join('')}</div><div class="format-rule-grid">${tab==='base'?`${select('font','正文字体',['宋体','黑体','仿宋','Times New Roman'].map(v=>[v,v]))}${select('size','正文字号',sizes)}${select('line','行距',[[1,'单倍'],[1.25,'1.25 倍'],[1.5,'1.5 倍'],[2,'2 倍']])}${select('indent','首行缩进',[[0,'无缩进'],[2,'2 字符']])}${['top','bottom','left','right'].map((k,i)=>`<label>${['上','下','左','右'][i]}页边距（cm）<input type="number" min="1" max="5" step="0.1" data-rule="${k}" aria-label="${['上','下','左','右'][i]}页边距" value="${rules[k]}"></label>`).join('')}`:tab==='heading'?`${[1,2,3].map(n=>select('h'+n,n+' 级标题字号',sizes)).join('')}<p class="hub-footnote">标题统一黑体。依据原有大纲级别或“第一章”“1.1 标题”等文本识别，可在右侧手动校正。</p>`:`${[['body','正文样式'],['headings','标题字体与层级'],['margins','所有分节页边距']].map(([k,t])=>`<label class="research-check"><input type="checkbox" data-rule="${k}" ${rules[k]?'checked':''}>${t}</label>`).join('')}<p class="hub-footnote">仅处理正文顶层段落。表格内部、页眉页脚、批注与公式不自动排版。</p>`}</div><div class="research-actions"><button class="btn secondary" data-action="check">检查格式</button>${formatService==='smart'?`<button class="btn primary" data-action="apply" ${doc.blocked?'disabled':''}>应用选定修改</button>`:''}</div><p id="format-status" class="hub-footnote" role="status">${dirty?'有未保存修改。':applied?'已应用排版，可导出 Word。':'原始文件保留，应用前请核对范围。'}</p><button class="btn secondary" data-action="example">使用示例</button><div class="format-warnings">${doc.warnings.map(w=>`<p>${esc(w)}</p>`).join('')}<p>连续预览仅展示正文文本；图片、表格、公式及真实分页请在 Word 中核对。</p></div></section><div class="format-review-column"><section class="card format-preview doc-detail-panel"><div class="hub-card-heading"><h2>文档预览</h2><small>连续预览 · 非 Word 分页</small></div><div class="format-preview-toolbar"><div class="research-tabs">${[['original','原始文档'],['formatted','排版预览']].map(([v,t])=>`<button data-view="${v}" class="${view===v?'active':''}" ${v==='formatted'&&!applied?'disabled':''}>${t}</button>`).join('')}</div><label>定位段落<select id="format-focus" aria-label="定位段落">${doc.paragraphs.map((p,i)=>`<option value="${i}" ${focus===i?'selected':''}>${i+1}. ${esc(p.text.slice(0,18))}</option>`).join('')}</select></label></div><div class="format-paper-wrap"><article class="format-paper" style="padding:${previewMargins()}">${doc.paragraphs.map((p,i)=>paragraph(p,i)).join('')}</article></div></section><section class="card format-results doc-detail-panel"><div class="hub-card-heading"><h2>格式检查结果</h2><span class="hub-badge">${checked?`${fix} 项可修正 · ${unknown} 项待确认`:'尚未检查'}</span></div>${checked?`<p class="hub-footnote">${applied?'原件检查结果保留，修改清单可供对照。':'检查原件与当前规则；不能确定的格式不会当作已验证合格。'}</p><div class="format-issues">${issues.map((issue,i)=>`<div class="format-issue"><div><b>${issue.index!=null?'段落 '+(issue.index+1):'分节 '+(issue.section+1)} · ${issue.label}</b><p>${esc(issue.current)} → ${esc(issue.target)}</p></div><span class="hub-badge ${issue.status==='unknown'?'gray':''}">${issue.status==='unknown'?'需确认':'可修正'}</span>${issue.index!=null?`<button class="text-btn" data-locate="${issue.index}">查看位置</button>`:''}</div>`).join('')||'<p class="hub-footnote">当前检查范围内未发现差异。复杂对象不在自动检查范围内。</p>'}</div>`:`<div class="research-empty format-check-empty"><span aria-hidden="true">${formatServiceIcon('check',34)}</span><h3>格式问题，会在这里清晰呈现</h3><p>核对规则后点击“检查格式”，查看实际问题的位置与修改建议。</p><small>当前还没有生成检测结果，不代表格式已经合格。</small></div>`}</section><div class="format-footer"><span>原始文件保留 · 修改可核对</span><div class="research-actions">${formatService==='check'?`<button class="btn secondary" data-action="report-export" ${!checked?'disabled':''}>导出检测清单</button>`:`<button class="btn secondary" data-action="log" ${!applied?'disabled':''}>修改清单</button>`}<button class="btn secondary" data-action="save">保存记录</button>${formatService==='smart'?`<button class="btn primary" data-action="export" ${!applied?'disabled':''}>导出排版 Word</button>`:''}</div></div></div></div><p class="hub-footnote">当前为本地排版，不上传文档。DOCX 最大 2MB；保存包括原件，浏览器空间不足时请先下载文件。目录、参考文献规范与页码不会自动重建。</p></div>`;bindDrop();}
function previewMargins(){const m=view==='formatted'&&applied&&rules.margins?rules:doc.sections[0]||{};return ['top','right','bottom','left'].map(k=>Math.max(12,Number(m[k]||2.5)*14)+'px').join(' ');}
function paragraph(p,i){const f=p.format,formatted=view==='formatted'&&applied,head=p.level>0,selected=formatted&&(head?rules.headings:rules.body),font=selected?(head?'黑体':rules.font):f.font?.[0]||'宋体',size=selected?Number(head?rules['h'+Math.min(p.level,3)]:rules.size):f.size?.[0]||12,line=selected&&!head?rules.line:f.line?.[0]||1.5,indent=selected&&!head?rules.indent:f.indent?.[0]||0;return `<section id="format-p-${i}" class="format-paragraph ${focus===i?'focused':''}"><p style="font-family:${esc(/^[\p{L}\p{N} -]{1,60}$/u.test(font)?font:'宋体')};font-size:${Math.max(6,Math.min(36,Number(size)||12))}pt;line-height:${Math.max(1,Math.min(3,Number(line)||1.5))};text-indent:${Math.max(0,Math.min(5,Number(indent)||0))}em">${esc(p.text)}</p><label class="format-role">段落 ${i+1}<select data-level="${i}" aria-label="段落 ${i+1} 类型">${[[0,'正文'],[1,'一级标题'],[2,'二级标题'],[3,'三级标题']].map(([v,t])=>`<option value="${v}" ${p.level===v?'selected':''}>${t}</option>`).join('')}</select></label></section>`;}
function invalidate(){checked=false;applied=null;view='original';dirty=true;}
function changes(e){const t=e.target;if(e.type==='input'&&['format-file','format-template','format-template-flow'].includes(t.id))return;if(t.id==='format-file'||t.id==='format-file-flow'){readFile(t.files[0]);return;}if(t.dataset.rule){templateChoice='custom';root.querySelectorAll('#format-template,#format-template-flow').forEach(select=>select.value='custom');rules[t.dataset.rule]=t.type==='checkbox'?t.checked:t.tagName==='SELECT'&&t.dataset.rule==='font'?t.value:Number(t.value);invalidate();$('#format-status').textContent='规则已修改，请重新检查并应用。';root.querySelectorAll('[data-action="export"],[data-action="log"]').forEach(button=>button.disabled=true);root.querySelector('[data-view="formatted"]').disabled=true;root.querySelector('.format-paper').style.padding=previewMargins();root.querySelector('.format-paper').innerHTML=doc.paragraphs.map((p,i)=>paragraph(p,i)).join('');root.querySelector('[data-view="original"]').classList.add('active');root.querySelector('[data-view="formatted"]').classList.remove('active');root.querySelector('.format-results').innerHTML='<h2>格式检查结果</h2><p class="hub-footnote">规则已改变，请重新检查。</p>';}else if(t.id==='format-template'||t.id==='format-template-flow'){setTemplate(t.value);}else if(t.id==='format-project'){item.projectId=t.value;dirty=true;}else if(t.id==='format-title'){item.title=t.value;dirty=true;}else if(t.dataset.level){doc.paragraphs[Number(t.dataset.level)].level=Number(t.value);invalidate();draw();}else if(t.id==='format-focus'){focus=Number(t.value);locate();}}
function setTemplate(value){if(value==='custom'){templateChoice='custom';dirty=true;draw();return;}if(!confirm('替换当前排版规则？')){root.querySelectorAll('#format-template,#format-template-flow').forEach(select=>select.value=templateChoice);return;}templateChoice=value;rules=defaultRules();if(value==='graduate'){rules.line=2;rules.left=3;}invalidate();draw();}
function locate(){const target=$('#format-p-'+focus);root.querySelectorAll('.format-paragraph').forEach(p=>p.classList.toggle('focused',p===target));target?.scrollIntoView({block:'nearest',behavior:'smooth'});}
function freeze(value){root.querySelectorAll('button,input,select').forEach(e=>{if(value){e.dataset.previousDisabled=String(e.disabled);e.disabled=true;}else if(e.dataset.previousDisabled!=null){e.disabled=e.dataset.previousDisabled==='true';delete e.dataset.previousDisabled;}});}
async function readFile(file){const epoch=formatEpoch;if(!file||busy)return;if(!/\.docx$/i.test(file.name)||file.size>2*1024*1024)return ctx.notify('请选择 2MB 以内的 DOCX 文件；PDF 不支持原样排版。');busy=true;freeze(true);try{const next=new Uint8Array(await file.arrayBuffer()),parsed=await parseDocx(next);if(epoch!==formatEpoch)return;if(dirty&&!confirm('替换当前文档？建议先保存记录或下载文件。'))return;bytes=next;doc=parsed;item={title:file.name.replace(/\.docx$/i,'').slice(0,120),fileName:file.name,projectId:item.projectId||'',example:false};invalidate();focus=0;draw();ctx.notify('已读取原件。复杂对象的保留范围请查看提示。');}catch(e){if(epoch===formatEpoch)ctx.notify(e.message||'读取失败，原文档未替换。');}finally{if(epoch===formatEpoch){busy=false;freeze(false);}}}
function bindDrop(){const profile=currentFlow();const steps=root.querySelector('.format-steps');if(steps&&!root.querySelector('.format-services'))steps.insertAdjacentHTML('beforebegin',formatServiceCards());if(steps&&!root.querySelector('.format-mode-panel,.format-refine-panel'))steps.insertAdjacentHTML('afterend',formatModePanel());root.querySelectorAll('.format-step').forEach((step,i)=>{const data=profile.steps[i];if(!data)return;step.querySelector('strong').textContent=data[1];step.querySelector('small').textContent=data[2];});const pageHeading=root.querySelector('.hub-heading h1');const pageDesc=root.querySelector('.hub-heading p');if(pageHeading)pageHeading.textContent='格式排版';if(pageDesc)pageDesc.textContent=profile.desc;if(formatService==='refine'){const upload=root.querySelector('.format-flow-upload');if(upload)upload.innerHTML='<span class="format-refine-pending">格式模板上传服务待接入</span>';root.querySelector('#format-refine-file')?.addEventListener('change',e=>readFile(e.target.files[0]));}root.querySelectorAll('[data-format-service]').forEach(button=>button.addEventListener('click',()=>{if(formatService===button.dataset.formatService)return;formatService=button.dataset.formatService;formatStep=1;checked=false;view='original';dirty=true;draw();}));root.querySelectorAll('[data-template-choice]').forEach(button=>button.addEventListener('click',()=>setTemplate(['undergraduate','graduate','custom'][Number(button.dataset.templateChoice)]||'custom')));root.querySelectorAll('#format-template,#format-template-flow').forEach(select=>select.value=templateChoice);const search=root.querySelector('#format-school-search');search?.addEventListener('input',()=>{const query=search.value.trim().toLowerCase();const cards=[...root.querySelectorAll('[data-template-choice]')];cards.forEach(card=>{card.hidden=!!query&&!card.textContent.toLowerCase().includes(query);});const empty=root.querySelector('#format-template-empty');if(empty)empty.hidden=cards.some(card=>!card.hidden);});root.querySelector('[data-action="report"]')?.addEventListener('click',()=>{checked=true;draw();ctx.notify('格式检测报告已生成，请查看下方问题清单。');});root.querySelector('[data-action="refine-pending"]')?.addEventListener('click',()=>ctx.notify('格式精修在线服务尚未接入，当前不会提交或扣费。'));const zone=$('.format-file');zone.addEventListener('dragover',e=>e.preventDefault());zone.addEventListener('drop',e=>{e.preventDefault();if(e.dataTransfer.files.length===1)readFile(e.dataTransfer.files[0]);else ctx.notify('每次请选择一个文件。');});}
function changeLog(){return {title:item.title,example:item.example,rules,scope:'正文顶层段落及选择的分节页边距',paragraphs:doc.paragraphs.filter(p=>p.level?rules.headings:rules.body).map(p=>({paragraph:p.sourceIndex+1,type:p.level?'标题 '+p.level:'正文'})),originalIssues:checkFormatting(doc,rules),warnings:doc.warnings,note:'未自动修改表格、公式、图片、页眉页脚、批注或目录。'};}
async function actions(e){const epoch=formatEpoch;const b=e.target.closest('button');if(!b||busy)return;try{if(b.dataset.step){if(formatService==='refine')return;const n=Number(b.dataset.step);if(n<=formatStep||n===formatStep+1){formatStep=n;draw();}return;}if(b.dataset.tab){tab=b.dataset.tab;draw();return;}if(b.dataset.view){view=b.dataset.view;draw();return;}if(b.dataset.locate!=null){focus=Number(b.dataset.locate);locate();return;}switch(b.dataset.action){case 'next-step':if(formatStep===1){formatStep=2;draw();}else if(formatStep===2){formatStep=3;draw();}break;case 'prev-step':if(formatStep>1){formatStep-=1;draw();}break;case 'check':validateRules(rules);checked=true;if(formatService==='check')formatStep=4;draw();break;case 'report-export':if(!checked)throw new Error('请先检查格式。');download(item.title+'-格式检测清单.json',JSON.stringify({title:item.title,example:!!item.example,scope:'正文顶层段落及选择的分节页边距',rules,issues:checkFormatting(doc,rules),warnings:doc.warnings,note:'仅核对本地规则，不代表学校或期刊已审核合格。'},null,2),'application/json');break;case 'apply':if(formatService!=='smart')throw new Error('请切换到智能排版后应用修改。');validateRules(rules);busy=true;freeze(true);try{const output=await applyDocx(bytes,doc,rules);if(epoch!==formatEpoch)return;applied=output;checked=true;dirty=true;view='formatted';formatStep=4;draw();ctx.notify('已生成排版副本，原文件未修改。');}finally{if(epoch===formatEpoch){busy=false;freeze(false);}}break;case 'original':download(item.fileName||item.title+'-原件.docx',bytes,'application/vnd.openxmlformats-officedocument.wordprocessingml.document');break;case 'export':if(!applied)throw new Error('请先应用修改。');download(item.title+'-排版.docx',applied,'application/vnd.openxmlformats-officedocument.wordprocessingml.document');ctx.notify('已导出 DOCX，请在 Word 中核对最终分页。');break;case 'log':download(item.title+'-修改清单.json',JSON.stringify(changeLog(),null,2),'application/json');break;case 'save':validateRules(rules);if(!item.title.trim())throw new Error('请填写成果名称。');const all=list(keys.drafts),old=all.find(d=>d.id===item.id),now=new Date().toISOString();item={...item,id:item.id||crypto.randomUUID(),tool:'format',stage:'formatted',text:doc.paragraphs.map(p=>p.text).join('\n\n'),createdAt:old?.createdAt||now,updatedAt:now,formatting:{original:to64(bytes),rules,service:formatService,template:templateChoice,checked,applied:formatService==='smart'&&!!applied,levels:doc.paragraphs.map(p=>p.level)}};try{write(keys.drafts,old?all.map(d=>d.id===item.id?item:d):[item,...all]);}catch{throw new Error('浏览器空间不足，记录未保存，请先下载原件和排版文件。');}dirty=false;try{recordTask({id:'draft-'+item.id,title:item.title,kind:'排版记录保存',status:'completed',projectId:item.projectId,url:'#draft/'+item.id});}catch{}draw();ctx.notify('排版记录与原件已保存到当前浏览器。');break;case 'example':if(dirty&&!confirm('放弃未保存修改并打开示例？'))return;busy=true;freeze(true);try{const nextBytes=await exampleDocx();if(epoch!==formatEpoch)return;const nextDoc=await parseDocx(nextBytes);if(epoch!==formatEpoch)return;bytes=nextBytes;doc=nextDoc;item={title:'毕业论文示例',example:true,projectId:''};rules=defaultRules();templateChoice='custom';checked=false;applied=null;dirty=false;view='original';formatStep=1;focus=0;draw();}finally{if(epoch===formatEpoch){busy=false;freeze(false);}}break;}}catch(err){if(epoch===formatEpoch)ctx.notify(err.message||'操作失败，请先下载文件。');}}
